insert into public.yachts (slug, ordre, nom, invites, port, vente, location_basse, location_haute, fiche, traductions) values ('castellane', 2, 'Castellane', 12, 'Cannes', 34500000, null, null, '{"selection":true,"exclusivite":false,"type":"moteur","chantier":"Heesen","chantierCourt":"Heesen","annee":2022,"refit":null,"longueur":50,"largeur":9.2,"tirant":2.4,"coque":"Aluminium","architecte":"Frank Laupman, Omega Architects","cabines":"6 cabines : suite du propriétaire, 3 VIP, 2 twins","equipage":10,"vitesse":{"croisiere":14,"max":17},"autonomie":3800,"moteurs":"2 × MTU 16V 2000 M96L","stabilisateurs":"Gyroscopiques","pavillon":"Îles Caïmans","accroche":"Une coque bleu nuit, rapide et silencieuse, pensée pour les traversées.","description":["Castellane appartient à cette famille de yachts hollandais qui naviguent vite sans jamais se faire entendre. Sa coque en aluminium, bleu nuit, file à dix-sept nœuds et rejoint la Corse dans la journée.","À bord, le chêne clair et le lin sable adoucissent les lignes tendues de l''extérieur. Le beach club, à fleur d''eau, s''ouvre sur trois côtés quand le yacht est au mouillage aux îles de Lérins, son port d''attache."],"points":[["Beach club","Ouvert sur trois côtés, avec salle de sport et hammam"],["Vitesse","17 nœuds en pointe, 14 en croisière, avec une consommation mesurée"],["Entretien","Suivi par le chantier depuis sa livraison, historique complet disponible"]],"ponts":[["Pont soleil","Bains de soleil, bar, salle à manger d''extérieur"],["Pont supérieur","Salon du ciel, timonerie, cabine du capitaine"],["Pont principal","Salon, salle à manger, suite du propriétaire"],["Pont inférieur","3 cabines VIP, 2 twins, beach club"]],"image":{"src":"flotte/castellane","w":1536,"h":1024,"alt":"Le yacht Castellane, coque bleu nuit, au mouillage aux îles de Lérins"},"galerie":[{"src":"flotte/castellane","w":1536,"h":1024,"pont":"Extérieur","alt":"Castellane au mouillage dans les eaux turquoise des îles de Lérins"},{"src":"galerie/castellane-salon","w":1536,"h":1024,"pont":"Pont principal","alt":"Le salon de Castellane : chêne clair, lin sable et laque bleu marine, face aux îles de Lérins"},{"src":"galerie/castellane-suite","w":1536,"h":1024,"pont":"Pont principal","alt":"La suite du propriétaire, sur toute la largeur du yacht, ouverte sur la mer des deux côtés"},{"src":"galerie/castellane-beach-club","w":1536,"h":1024,"pont":"Pont inférieur","alt":"Le beach club de Castellane, ouvert sur la mer, plateformes dépliées au mouillage"},{"src":"galerie/castellane-pont-soleil","w":1536,"h":1024,"pont":"Pont soleil","alt":"Le pont soleil de Castellane au coucher du soleil, face à Cannes et à l''Estérel"}],"visite":{"dir":"visites/castellane","affiche":"visites/castellane/affiche","duree":"Sept étapes, des îles de Lérins à la suite du propriétaire.","pieces":{"V1":"Au mouillage, îles de Lérins","V2":"La poupe","V3":"Le beach club","V4":"Le pont arrière","V5":"Le salon","V6":"Le hall","V7":"La suite du propriétaire"}}}'::jsonb, '{"en":{"Aluminium":"Aluminium","Frank Laupman, Omega Architects":"Frank Laupman, Omega Architects","6 cabines : suite du propriétaire, 3 VIP, 2 twins":"6 cabins: owner''s suite, 3 VIPs, 2 twins","2 × MTU 16V 2000 M96L":"2 × MTU 16V 2000 M96L","Gyroscopiques":"Gyroscopic","Îles Caïmans":"Cayman Islands","Une coque bleu nuit, rapide et silencieuse, pensée pour les traversées.":"A navy hull, fast and silent, built for passages.","Castellane appartient à cette famille de yachts hollandais qui naviguent vite sans jamais se faire entendre. Sa coque en aluminium, bleu nuit, file à dix-sept nœuds et rejoint la Corse dans la journée.":"Castellane belongs to that family of Dutch yachts that move fast without ever making themselves heard. Her navy aluminium hull runs at seventeen knots and reaches Corsica within the day.","À bord, le chêne clair et le lin sable adoucissent les lignes tendues de l''extérieur. Le beach club, à fleur d''eau, s''ouvre sur trois côtés quand le yacht est au mouillage aux îles de Lérins, son port d''attache.":"On board, light oak and sand‑coloured linen soften the taut lines of her exterior. The beach club, at water level, opens on three sides when she lies at anchor off the Lérins islands, her home waters.","Beach club":"Beach club","Ouvert sur trois côtés, avec salle de sport et hammam":"Open on three sides, with gym and hammam","Vitesse":"Speed","17 nœuds en pointe, 14 en croisière, avec une consommation mesurée":"17 knots maximum, 14 cruising, with measured consumption","Entretien":"Maintenance","Suivi par le chantier depuis sa livraison, historique complet disponible":"Serviced by the builder since delivery, full history available","Pont soleil":"Sun deck","Bains de soleil, bar, salle à manger d''extérieur":"Sunpads, bar, outdoor dining","Pont supérieur":"Upper deck","Salon du ciel, timonerie, cabine du capitaine":"Sky lounge, wheelhouse, captain''s cabin","Pont principal":"Main deck","Salon, salle à manger, suite du propriétaire":"Saloon, dining room, owner''s suite","Pont inférieur":"Lower deck","3 cabines VIP, 2 twins, beach club":"3 VIP cabins, 2 twins, beach club","Le yacht Castellane, coque bleu nuit, au mouillage aux îles de Lérins":"The yacht Castellane, with her navy hull, at anchor off the Lérins islands","Extérieur":"Exterior","Castellane au mouillage dans les eaux turquoise des îles de Lérins":"Castellane at anchor in the turquoise waters of the Lérins islands","Le salon de Castellane : chêne clair, lin sable et laque bleu marine, face aux îles de Lérins":"Castellane''s saloon: light oak, sand linen and navy lacquer, facing the Lérins islands","La suite du propriétaire, sur toute la largeur du yacht, ouverte sur la mer des deux côtés":"The owner''s suite, spanning the full beam, open to the sea on both sides","Le beach club de Castellane, ouvert sur la mer, plateformes dépliées au mouillage":"Castellane''s beach club, open to the sea, platforms unfolded at anchor","Le pont soleil de Castellane au coucher du soleil