insert into public.yachts (slug, ordre, nom, invites, port, vente, location_basse, location_haute, fiche, traductions) values ('mistral-blanc', 3, 'Mistral Blanc', 12, 'Monaco', null, 185000, 215000, '{"selection":true,"exclusivite":false,"type":"moteur","chantier":"Benetti","chantierCourt":"Benetti","annee":2019,"refit":2024,"longueur":44.5,"largeur":8.6,"tirant":2.5,"coque":"Acier et aluminium","architecte":"Giorgio M. Cassetta","cabines":"6 cabines : suite du propriétaire, 2 VIP, 2 doubles, 1 twin","equipage":9,"vitesse":{"croisiere":12,"max":15},"autonomie":3500,"moteurs":"2 × Caterpillar C32","stabilisateurs":"À ailerons, actifs au mouillage","pavillon":"Monaco","accroche":"L''élégance italienne, à quai à Monaco, prête à appareiller.","description":["Mistral Blanc a été livré à Livourne et entièrement rafraîchi en 2024 : laque blanche, frêne clair, cuir ivoire et touches d''or pâle. Tout y est lumineux, jusqu''au grand salon du pont principal.","Basé à Monaco, il part volontiers vers Portofino ou la Corse. Son chef a travaillé dix ans dans des maisons étoilées de la Riviera ; la table se dresse sur le pont arrière, face au port qui s''illumine."],"points":[["Table","Un chef formé dans les maisons étoilées de la Riviera"],["Refit 2024","Intérieurs, literie et équipements audiovisuels renouvelés"],["Au départ de Monaco","Portofino, la Corse ou les îles de Lérins en une journée"]],"ponts":[["Pont soleil","Jacuzzi, bains de soleil, bar"],["Pont supérieur","Salon du ciel, salle à manger d''extérieur"],["Pont principal","Salon, salle à manger, suite du propriétaire"],["Pont inférieur","2 VIP, 2 doubles, 1 twin"]],"image":{"src":"flotte/mistral-blanc","w":1536,"h":1024,"alt":"Le yacht Mistral Blanc à quai à Port Hercule, Monaco, à l''heure bleue"},"galerie":[{"src":"flotte/mistral-blanc","w":1536,"h":1024,"pont":"Extérieur","alt":"Mistral Blanc à quai à Port Hercule, éclairé à l''heure bleue"},{"src":"galerie/mistral-blanc-salon","w":1536,"h":1024,"pont":"Pont principal","alt":"Le grand salon de Mistral Blanc : laque blanche, cuir ivoire et or pâle, face au port de Monaco"},{"src":"galerie/mistral-blanc-suite","w":1536,"h":1024,"pont":"Pont principal","alt":"La suite du propriétaire, ouverte sur sa terrasse privée et la mer"},{"src":"galerie/mistral-blanc-diner","w":1536,"h":1024,"pont":"Pont supérieur","alt":"La table dressée pour dix sur le pont, face à Monaco illuminé"},{"src":"galerie/mistral-blanc-jacuzzi","w":1536,"h":1024,"pont":"Pont soleil","alt":"Le jacuzzi et le bar du pont soleil au coucher du soleil, sur la côte vers le cap Martin"}],"visite":{"dir":"visites/mistral-blanc","affiche":"visites/mistral-blanc/affiche","duree":"Six étapes, du quai de Monaco au pont soleil, à l''heure bleue.","pieces":{"V1":"À quai, Port Hercule","V2":"Le pont arrière","V3":"Le salon","V4":"L''escalier","V5":"Le pont soleil","V6":"Face à Monaco"}}}'::jsonb, '{"en":{"Acier et aluminium":"Steel and aluminium","Giorgio M. Cassetta":"Giorgio M. Cassetta","6 cabines : suite du propriétaire, 2 VIP, 2 doubles, 1 twin":"6 cabins: owner''s suite, 2 VIPs, 2 doubles, 1 twin","2 × Caterpillar C32":"2 × Caterpillar C32","À ailerons, actifs au mouillage":"Fin stabilisers, active at anchor","L''élégance italienne, à quai à Monaco, prête à appareiller.":"Italian elegance, moored in Monaco, ready to cast off.","Mistral Blanc a été livré à Livourne et entièrement rafraîchi en 2024 : laque blanche, frêne clair, cuir ivoire et touches d''or pâle. Tout y est lumineux, jusqu''au grand salon du pont principal.":"Mistral Blanc was delivered in Livorno and fully refreshed in 2024: white lacquer, pale ash, ivory leather and touches of soft gold. Everything aboard is filled with light, right up to the grand saloon on the main deck.","Basé à Monaco, il part volontiers vers Portofino ou la Corse. Son chef a travaillé dix ans dans des maisons étoilées de la Riviera ; la table se dresse sur le pont arrière, face au port qui s''illumine.":"Based in Monaco, she happily heads for Portofino or Corsica. Her chef spent ten years in Michelin‑starred houses on the Riviera; the table is laid on the aft deck, facing the harbour as it lights up.","Table":"Dining","Un chef formé dans les maisons étoilées de la Riviera":"A chef trained in the Riviera''s Michelin‑starred houses","Refit 2024":"2024 refit","Intérieurs, literie et équipements audiovisuels renouvelés":"Interiors, bedding and audiovisual equipment renewed","Au départ de Monaco":"Departing Monaco","Portofino, la Corse ou les îles de Lérins en une journée":"Portofino, Corsica or the Lérins islands within a day","Pont soleil":"Sun deck","Jacuzzi, bains de soleil, bar":"Jacuzzi, sunpads, bar","Pont supérieur":"Upper deck","Salon du ciel, salle à manger d''extérieur":"Sky lounge, outdoor dining","Pont principal":"Main deck","Salon, salle à manger, suite du propriétaire":"Saloon, dining room, owner''s suite","Pont inférieur":"Lower deck","2 VIP, 2 doubles, 1 twin":"2 VIPs, 2 doubles, 1 twin","Le yacht Mistral Blanc à quai à Port Hercule, Monaco, à l''heure bleue":"The yacht Mistral Blanc moored in Port Hercule, Monaco, at blue hour","Extérieur":"Exterior","Mistral Blanc à quai à Port Hercule, éclairé à l''heure bleue":"Mistral Blanc moored in Port Hercule, lit up at blue hour","Le grand salon de Mistral Blanc : laque blanche, cuir ivoire et or pâle, face au port de Monaco":"Mistral Blanc''s grand saloon: white lacquer, ivory leather and soft gold, facing the port of Monaco","La suite du propriétaire, ouverte sur sa terrasse privée et la mer":"The owner''s suite, opening onto its private terrace and the sea","La table dressée pour dix sur le pont, face à Monaco illuminé":"The table laid for ten on deck, facing Monaco lit up at night","Le jacuzzi et le bar du pont soleil au coucher du soleil, sur la côte vers le cap Martin":"The sun deck''s jacuzzi and bar at sunset, looking along the coast to Cap Martin","À quai, Port Hercule":"Moored, Port Hercule","Le pont arrière":"The aft deck","Le salon":"The saloon","L''escalier":"The staircase","Le pont soleil":"The sun deck","Face à Monaco":"Facing Monaco"},"de":{"Acier et aluminium":"Stahl und Aluminium","Giorgio M. Cassetta":"Giorgio M. Cassetta","6 cabines : suite du propriétaire, 2 VIP, 2 doubles, 1 twin":"6 Kabinen: Eignersuite, 2 VIP, 2 Doppel, 1 Twin","2 × Caterpillar C32":"2 × Caterpillar C32","À ailerons, actifs au mouillage":"Flossenstabilisatoren, auch vor Anker aktiv","L''élégance italienne, à quai à Monaco, prête à appareiller.":"Italienische Eleganz, am Kai in Monaco, bereit zum Ablegen.","Mistral Blanc a été livré à Livourne et entièrement rafraîchi en 2024 : laque blanche, frêne clair, cuir ivoire et touches d''or pâle. Tout y est lumineux, jusqu''au grand salon du pont principal.":"Mistral Blanc wurde in Livorno abgeliefert und 2024 vollständig aufgefrischt: weißer Lack, helle Esche, elfenbeinfarbenes Leder und Akzente in hellem Gold. Alles ist hell, bis hin zum großen Salon auf dem Hauptdeck.","Basé à Monaco, il part volontiers vers Portofino ou la Corse. Son chef a travaillé dix ans dans des maisons étoilées de la Riviera ; la table se dresse sur le pont arrière, face au port qui s''illumine.":"In Monaco stationiert, bricht sie gern nach Portofino oder Korsika auf. Ihr Koch arbeitete zehn Jahre in Sternehäusern der Riviera; gedeckt wird auf dem Achterdeck, mit Blick auf den Hafen, wenn die Lichter angehen.","Table":"Küche","Un chef formé dans les maisons étoilées de la Riviera":"Ein Koch aus den Sternehäusern der Riviera","Refit 2024":"Refit 2024","Intérieurs, literie et équipements audiovisuels renouvelés":"Innenausstattung, Bettwäsche und Audio-Video-Technik erneuert","Au départ de Monaco":"Ab Monaco","Portofino, la Corse ou les îles de Lérins en une journée":"Portofino, Korsika oder die Lérins-Inseln an einem Tag","Pont soleil":"Sonnendeck","Jacuzzi, bains de soleil, bar":"Whirlpool, Sonnenliegen, Bar","Pont supérieur":"Oberdeck","Salon du ciel, salle à manger d''extérieur":"Sky Lounge, Essbereich im Freien","Pont principal":"Hauptdeck","Salon, salle à manger, suite du propriétaire":"Salon, Esszimmer, Eignersuite","Pont inférieur":"Unterdeck","2 VIP, 2 doubles, 1 twin":"2 VIP, 2 Doppel, 1 Twin","Le yacht Mistral Blanc à quai à Port Hercule, Monaco, à l''heure bleue":"Die Yacht Mistral Blanc am Kai in Port Hercule, Monaco, zur blauen Stunde","Extérieur":"Außen","Mistral Blanc à quai à Port Hercule, éclairé à l''heure bleue":"Mistral Blanc am Kai in Port Hercule, zur blauen Stunde beleuchtet","Le grand salon de Mistral Blanc : laque blanche, cuir ivoire et or pâle, face au port de Monaco":"Der große Salon der Mistral Blanc: weißer Lack, elfenbeinfarbenes Leder und helles Gold, mit Blick auf den Hafen von Monaco","La suite du propriétaire, ouverte sur sa terrasse privée et la mer":"Die Eignersuite, zu ihrer privaten Terrasse und zum Meer hin geöffnet","La table dressée pour dix sur le pont, face à Monaco illuminé":"Der Tisch für zehn an Deck gedeckt, mit Blick auf das beleuchtete Monaco","Le jacuzzi et le bar du pont soleil au coucher du soleil, sur la côte vers le cap Martin":"Whirlpool und Bar auf dem Sonnendeck bei Sonnenuntergang, entlang der Küste bis Cap Martin","À quai, Port Hercule":"Am Kai, Port Hercule","Le pont arrière":"Das Achterdeck","Le salon":"Der Salon","L''escalier":"Die Treppe","Le pont soleil":"Das Sonnendeck","Face à Monaco":"Mit Blick auf Monaco"},"it":{"Acier et aluminium":"Acciaio e alluminio","Giorgio M. Cassetta":"Giorgio M. Cassetta","6 cabines : suite du propriétaire, 2 VIP, 2 doubles, 1 twin":"6 cabine: suite armatoriale, 2 VIP, 2 doppie, 1 twin","2 × Caterpillar C32":"2 × Caterpillar C32","À ailerons, actifs au mouillage":"Ad alette, attivi all''ancora","L''élégance italienne, à quai à Monaco, prête à appareiller.":"L''eleganza italiana, in banchina a Monaco, pronta a salpare.","Mistral Blanc a été livré à Livourne et entièrement rafraîchi en 2024 : laque blanche, frêne clair, cuir ivoire et touches d''or pâle. Tout y est lumineux, jusqu''au grand salon du pont principal.":"Mistral Blanc è stato consegnato a Livorno e interamente rinnovato nel 2024: lacca bianca, frassino chiaro, pelle avorio e tocchi d''oro pallido. Tutto è luminoso, fino al grande salone del ponte principale.","Basé à Monaco, il part volontiers vers Portofino ou la Corse. Son chef a travaillé dix ans dans des maisons étoilées de la Riviera ; la table se dresse sur le pont arrière, face au port qui s''illumine.":"Con base a Monaco, parte volentieri verso Portofino o la Corsica. Il suo chef ha lavorato dieci anni in ristoranti stellati della Riviera; la tavola si apparecchia sul ponte di poppa, di fronte al porto che si illumina.","Table":"Tavola","Un chef formé dans les maisons étoilées de la Riviera":"Uno chef formato nei ristoranti stellati della Riviera","Refit 2024":"Refit 2024","Intérieurs, literie et équipements audiovisuels renouvelés":"Interni, biancheria e impianti audiovisivi rinnovati","Au départ de Monaco":"Con partenza da Monaco","Portofino, la Corse ou les îles de Lérins en une journée":"Portofino, la Corsica o le isole di Lérins in giornata","Pont soleil":"Sun deck","Jacuzzi, bains de soleil, bar":"Jacuzzi, prendisole, bar","Pont supérieur":"Ponte superiore","Salon du ciel, salle à manger d''extérieur":"Sky lounge, zona pranzo esterna","Pont principal":"Ponte principale","Salon, salle à manger, suite du propriétaire":"Salone, sala da pranzo, suite armatoriale","Pont inférieur":"Ponte inferiore","2 VIP, 2 doubles, 1 twin":"2 VIP, 2 doppie, 1 twin","Le yacht Mistral Blanc à quai à Port Hercule, Monaco, à l''heure bleue":"Lo yacht Mistral Blanc in banchina a Port Hercule, Monaco, all''ora blu","Extérieur":"Esterni","Mistral Blanc à quai à Port Hercule, éclairé à l''heure bleue":"Mistral Blanc in banchina a Port Hercule, illuminato all''ora blu","Le grand salon de Mistral Blanc : laque blanche, cuir ivoire et or pâle, face au port de Monaco":"Il grande salone di Mistral Blanc: lacca bianca, pelle avorio