insert into public.yachts (slug, ordre, nom, invites, port, vente, location_basse, location_haute, fiche, traductions) values ('solenne', 4, 'Solenne', 8, 'Saint-Tropez', null, 72000, 85000, '{"selection":true,"exclusivite":false,"type":"voile","chantier":"Perini Navi","chantierCourt":"Perini Navi","annee":2012,"refit":2021,"longueur":38,"largeur":8.3,"tirant":3.6,"coque":"Acier, superstructure en aluminium","architecte":"Ron Holland","cabines":"4 cabines : suite du propriétaire, 2 doubles, 1 twin","equipage":6,"vitesse":{"croisiere":11,"max":14},"autonomie":3000,"moteurs":"1 × Caterpillar C18","stabilisateurs":"Ketch, voiles sur enrouleurs","pavillon":"Royaume-Uni","accroche":"Un ketch à coque verte, pour naviguer vraiment.","description":["Solenne est un voilier que l''on mène à six, sans effort, grâce aux enrouleurs dessinés par son chantier. Le cockpit en teck s''abrite sous un bimini, la barre à roue se partage avec qui veut apprendre.","Sous le pont, le teck verni, la toile crème et le cuir vert forêt rappellent les grands voiliers d''autrefois. Porquerolles, Port-Cros et le Levant sont à une demi-journée de voile de Saint-Tropez."],"points":[["À la voile","14 nœuds sous voiles, manœuvres automatisées"],["Refit 2021","Gréement, voiles et intérieurs renouvelés"],["Les îles d''Or","Porquerolles, Port-Cros et le Levant à une demi-journée"]],"ponts":[["Pont","Cockpit arrière, salon de pont, bains de soleil à l''avant"],["Pont inférieur","Suite du propriétaire, 2 doubles, 1 twin, carré"]],"image":{"src":"flotte/solenne","w":1536,"h":1024,"alt":"Le voilier Solenne, ketch à coque verte, sous voiles devant Porquerolles"},"galerie":[{"src":"flotte/solenne","w":1536,"h":1024,"pont":"Extérieur","alt":"Solenne sous voiles devant l''île de Porquerolles"},{"src":"galerie/solenne-cockpit","w":1536,"h":1024,"pont":"Pont","alt":"Le cockpit de Solenne et ses deux barres à roue, sous voiles vers Porquerolles"},{"src":"galerie/solenne-mouillage","w":1536,"h":1024,"pont":"Pont","alt":"Le pont avant en teck au mouillage, dans une crique turquoise de Porquerolles"},{"src":"galerie/solenne-carre","w":1536,"h":1024,"pont":"Pont inférieur","alt":"Le carré de Solenne : teck verni, toile crème, cuir vert forêt et hublots en laiton"},{"src":"galerie/solenne-cabine","w":1536,"h":1024,"pont":"Pont inférieur","alt":"La cabine du propriétaire, lambrissée de teck, ouverte sur la mer par deux hublots"}],"visite":{"dir":"visites/solenne","affiche":"visites/solenne/affiche","duree":"Sept étapes, de la crique de Porquerolles à la cabine du propriétaire.","pieces":{"V1":"Au mouillage, Porquerolles","V2":"La poupe","V3":"Le cockpit","V4":"La descente","V5":"Le carré","V6":"La coursive","V7":"La cabine du propriétaire"}}}'::jsonb, '{"en":{"Acier, superstructure en aluminium":"Steel, aluminium superstructure","Ron Holland":"Ron Holland","4 cabines : suite du propriétaire, 2 doubles, 1 twin":"4 cabins: owner''s suite, 2 doubles, 1 twin","1 × Caterpillar C18":"1 × Caterpillar C18","Ketch, voiles sur enrouleurs":"Ketch, furling sails","Royaume-Uni":"United Kingdom","Un ketch à coque verte, pour naviguer vraiment.":"A green‑hulled ketch, for real sailing.","Solenne est un voilier que l''on mène à six, sans effort, grâce aux enrouleurs dessinés par son chantier. Le cockpit en teck s''abrite sous un bimini, la barre à roue se partage avec qui veut apprendre.":"Solenne is a sailing yacht you can handle with six aboard, effortlessly, thanks to the furling systems designed by her yard. The teak cockpit shelters under a bimini, and the wheel is shared with anyone who wants to learn.","Sous le pont, le teck verni, la toile crème et le cuir vert forêt rappellent les grands voiliers d''autrefois. Porquerolles, Port-Cros et le Levant sont à une demi-journée de voile de Saint-Tropez.":"Below deck, varnished teak, cream canvas and forest‑green leather recall the great sailing yachts of old. Porquerolles, Port‑Cros and the Levant are half a day''s sail from Saint‑Tropez.","À la voile":"Under sail","14 nœuds sous voiles, manœuvres automatisées":"14 knots under sail, automated handling","Refit 2021":"2021 refit","Gréement, voiles et intérieurs renouvelés":"Rigging, sails and interiors renewed","Les îles d''Or":"The Îles d''Or","Porquerolles, Port-Cros et le Levant à une demi-journée":"Porquerolles, Port‑Cros and the Levant within half a day","Pont":"Deck","Cockpit arrière, salon de pont, bains de soleil à l''avant":"Aft cockpit, deck saloon, sunpads forward","Pont inférieur":"Lower deck","Suite du propriétaire, 2 doubles, 1 twin, carré":"Owner''s suite, 2 doubles, 1 twin, saloon","Le voilier Solenne, ketch à coque verte, sous voiles devant Porquerolles":"The sailing yacht Solenne, a green‑hulled ketch, under sail off Porquerolles","Extérieur":"Exterior","Solenne sous voiles devant l''île de Porquerolles":"Solenne under sail off the island of Porquerolles","Le cockpit de Solenne et ses deux barres à roue, sous voiles vers Porquerolles":"Solenne''s cockpit and its twin wheels, under sail towards Porquerolles","Le pont avant en teck au mouillage, dans une crique turquoise de Porquerolles":"The teak foredeck at anchor, in a turquoise cove on Porquerolles","Le carré de Solenne : teck verni, toile crème, cuir vert forêt et hublots en laiton":"Solenne''s saloon: varnished teak, cream canvas, forest‑green leather and brass portholes","La cabine du propriétaire, lambrissée de teck, ouverte sur la mer par deux hublots":"The owner''s cabin, panelled in teak, opening onto the sea through two portholes","Au mouillage, Porquerolles":"At anchor, Porquerolles","La poupe":"The stern","Le cockpit":"The cockpit","La descente":"The companionway","Le carré":"The saloon below","La coursive":"The passageway","La cabine du propriétaire":"The owner''s cabin"},"de":{"Acier, superstructure en aluminium":"Stahl, Aufbau aus Aluminium","Ron Holland":"Ron Holland","4 cabines : suite du propriétaire, 2 doubles, 1 twin":"4 Kabinen: Eignersuite, 2 Doppel, 1 Twin","1 × Caterpillar C18":"1 × Caterpillar C18","Ketch, voiles sur enrouleurs":"Ketsch, Rollsegel","Royaume-Uni":"Vereinigtes Königreich","Un ketch à coque verte, pour naviguer vraiment.":"Ein Ketsch mit grünem Rumpf, zum richtigen Segeln.","Solenne est un voilier que l''on mène à six, sans effort, grâce aux enrouleurs dessinés par son chantier. Le cockpit en teck s''abrite sous un bimini, la barre à roue se partage avec qui veut apprendre.":"Solenne ist eine Segelyacht, die sich dank der von ihrer Werft entworfenen Rollanlagen mühelos zu sechst segeln lässt. Das Teakcockpit liegt geschützt unter einem Bimini, und das Steuerrad teilt man mit jedem, der es lernen möchte.","Sous le pont, le teck verni, la toile crème et le cuir vert forêt rappellent les grands voiliers d''autrefois. Porquerolles, Port-Cros et le Levant sont à une demi-journée de voile de Saint-Tropez.":"Unter Deck erinnern lackiertes Teak, cremefarbenes Segeltuch und waldgrünes Leder an die großen Segelyachten vergangener Zeiten. Porquerolles, Port‑Cros und die Île du Levant liegen einen halben Segeltag von Saint‑Tropez entfernt.","À la voile":"Unter Segeln","14 nœuds sous voiles, manœuvres automatisées":"14 Knoten unter Segeln, automatisierte Manöver","Refit 2021":"Refit 2021","Gréement, voiles et intérieurs renouvelés":"Rigg, Segel und Innenausstattung erneuert","Les îles d''Or":"Die Goldenen Inseln","Porquerolles, Port-Cros et le Levant à une demi-journée":"Porquerolles, Port‑Cros und die Île du Levant in einem halben Tag","Pont":"Deck","Cockpit arrière, salon de pont, bains de soleil à l''avant":"Achtercockpit, Deckssalon, Sonnenliegen am Vorschiff","Pont inférieur":"Unterdeck","Suite du propriétaire, 2 doubles, 1 twin, carré":"Eignersuite, 2 Doppel, 1 Twin, Salon","Le voilier Solenne, ketch à coque verte, sous voiles devant Porquerolles":"Die Segelyacht Solenne, ein Ketsch mit grünem Rumpf, unter Segeln vor Porquerolles","Extérieur":"Außen","Solenne sous voiles devant l''île de Porquerolles":"Solenne unter Segeln vor der Insel Porquerolles","Le cockpit de Solenne et ses deux barres à roue, sous voiles vers Porquerolles":"Das Cockpit der Solenne mit seinen zwei Steuerrädern, unter Segeln Richtung Porquerolles","Le pont avant en teck au mouillage, dans une crique turquoise de Porquerolles":"Das Vorschiff aus Teak vor Anker, in einer türkisfarbenen Bucht von Porquerolles","Le carré de Solenne : teck verni, toile crème, cuir vert forêt et hublots en laiton":"Der Salon der Solenne: lackiertes Teak, cremefarbenes Segeltuch, waldgrünes Leder und Bullaugen aus Messing","La cabine du propriétaire, lambrissée de teck, ouverte sur la mer par deux hublots":"Die Eignerkabine, mit Teak vertäfelt, durch zwei Bullaugen zum Meer hin geöffnet","Au mouillage, Porquerolles":"Vor Anker, Porquerolles","La poupe":"Das Heck","Le cockpit":"Das Cockpit","La descente":"Der Niedergang","Le carré":"Der Salon unter Deck","La coursive":"Der Gang","La cabine du propriétaire":"Die Eignerkabine"},"it":{"Acier, superstructure en aluminium":"Acciaio, sovrastruttura in alluminio","Ron Holland":"Ron Holland","4 cabines : suite du propriétaire, 2 doubles, 1 twin":"4 cabine: suite armatoriale, 2 doppie, 1 twin","1 × Caterpillar C18":"1 × Caterpillar C18","Ketch, voiles sur enrouleurs":"Ketch, vele con avvolgitori","Royaume-Uni":"Regno Unito","Un ketch à coque verte, pour naviguer vraiment.":"Un ketch dallo scafo verde, per navigare davvero.","Solenne est un voilier que l''on mène à six, sans effort, grâce aux enrouleurs dessinés par son chantier. Le cockpit en teck s''abrite sous un bimini, la barre à roue se partage avec qui veut apprendre.":"Solenne è una barca a vela che si conduce in sei, senza fatica, grazie agli avvolgitori progettati dal suo cantiere. Il pozzetto in teak si ripara sotto un bimini, e la ruota del timone si condivide con chi vuole imparare.","Sous le pont, le teck verni, la toile crème et le cuir vert forêt rappellent les grands voiliers d''autrefois. Porquerolles, Port-Cros et le Levant sont à une demi-journée de voile de Saint-Tropez.":"Sottocoperta, il teak verniciato, la tela crema e la pelle verde foresta ricordano i grandi velieri di un tempo. Porquerolles, Port‑Cros e il Levant sono a mezza giornata di vela da Saint‑Tropez.","À la voile":"A vela","14 nœuds sous voiles, manœuvres automatisées":"14 nodi a vela, manovre automatizzate","Refit 2021":"Refit 2021","Gréement, voiles et intérieurs renouvelés":"Attrezzatura, vele e interni rinnovati","Les îles d''Or":"Le isole d''Oro","Porquerolles, Port-Cros et le Levant à une demi-journée":"Porquerolles, Port‑Cros e il Levant in mezza giornata","Pont":"Ponte","Cockpit arrière, salon de pont, bains de soleil à l''avant":"Pozzetto di poppa, salone di coperta, prendisole a prua","Pont inférieur":"Ponte inferiore","Suite du propriétaire, 2 doubles, 1 twin, carré":"Suite armatoriale, 2 doppie, 1 twin, dinette","Le voilier Solenne, ketch à coque verte, sous voiles devant Porquerolles":"La barca a vela Solenne, ketch dallo scafo verde, a vela davanti a Porquerolles","Extérieur":"Esterni","Solenne sous voiles devant l''île de Porquerolles":"Solenne a vela davanti all''isola di Porquerolles","Le cockpit de Solenne et ses deux barres à roue, sous voiles vers Porquerolles":"Il pozzetto di Solenne e le sue due ruote del timone, a vela verso Porquerolles","Le pont avant en teck au mouillage, dans une crique turquoise de Porquerolles":"Il ponte di prua in teak all''ancora, in una caletta turchese di Porquerolles","Le carré de Solenne : teck verni, toile crème, cuir vert forêt et hublots en laiton":"La dinette di Solenne: teak verniciato, tela crema, pelle verde foresta e oblò in ottone","La cabine du propriétaire, lambrissée de teck, ouverte sur la mer par deux hublots":"La cabina armatoriale, rivestita in teak, aperta sul mare da due oblò","Au mouillage, Porquerolles":"All''ancora, Porquerolles","La poupe":"La poppa","Le cockpit":"Il pozzetto","La descente":"La discesa","Le carré":"La dinette","La coursive":"Il corridoio","La cabine du propriétaire":"La cabina armatoriale"}}'::jsonb)
