insert into public.yachts (slug, ordre, nom, invites, port, vente, location_basse, location_haute, fiche, traductions) values ('tramontane', 5, 'Tramontane', 10, 'Saint-Raphaël', null, 95000, 110000, '{"selection":true,"exclusivite":false,"type":"moteur","chantier":"Custom Line","chantierCourt":"Custom Line","annee":2018,"refit":2023,"longueur":33,"largeur":7.2,"tirant":2.1,"coque":"Composite","architecte":"Francesco Paszkowski","cabines":"5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin","equipage":6,"vitesse":{"croisiere":22,"max":28},"autonomie":350,"moteurs":"2 × MTU 12V 2000 M96L","stabilisateurs":"Gyroscopiques","pavillon":"France","accroche":"Vingt-huit nœuds, et l''Estérel pour horizon.","description":["Tramontane est le plus vif de la flotte : il relie Saint-Tropez à Cannes en une heure, et laisse le temps de déjeuner aux îles de Lérins avant de rentrer. Sa coque grise et ses vitrages teintés lui donnent une allure de sport.","À bord, l''eucalyptus gris, le cuir noir et l''acier brossé composent un intérieur tenu, presque architectural. Le fly, abrité par un hard-top, devient le salon principal dès que le soleil est haut."],"points":[["28 nœuds","Saint-Tropez à Cannes en une heure"],["Fly","Salon, bar et bains de soleil à l''ombre d''un hard-top"],["Tirant d''eau réduit","Mouillages au plus près des calanques de l''Estérel"]],"ponts":[["Fly","Poste de pilotage, bar, salon d''extérieur, bains de soleil"],["Pont principal","Cockpit, salon, salle à manger, suite du propriétaire"],["Pont inférieur","1 VIP, 2 doubles, 1 twin"]],"image":{"src":"flotte/tramontane","w":1536,"h":1024,"alt":"Le yacht Tramontane lancé à pleine vitesse le long des roches rouges de l''Estérel"},"galerie":[{"src":"flotte/tramontane","w":1536,"h":1024,"pont":"Extérieur","alt":"Tramontane lancé à pleine vitesse le long de l''Estérel"},{"src":"galerie/tramontane-calanque","w":1536,"h":1024,"pont":"Extérieur","alt":"La plage arrière au ras de l''eau, au mouillage dans une calanque de l''Estérel"},{"src":"galerie/tramontane-salon","w":1536,"h":1024,"pont":"Pont principal","alt":"Le salon de Tramontane : eucalyptus gris, cuir noir et pierre claire, face aux roches rouges"},{"src":"galerie/tramontane-cabine","w":1536,"h":1024,"pont":"Pont principal","alt":"La cabine du propriétaire, tête de lit en cuir noir et baie ouverte sur l''Estérel"},{"src":"galerie/tramontane-fly","w":1536,"h":1024,"pont":"Fly","alt":"Le fly de Tramontane, abrité par son hard-top : bar, poste de pilotage et bains de soleil"}],"visite":{"dir":"visites/tramontane","affiche":"visites/tramontane/affiche","duree":"Six étapes, de la calanque de l''Estérel à la cabine du propriétaire.","pieces":{"V1":"Au mouillage, Estérel","V2":"La plage arrière","V3":"Le cockpit","V4":"Le salon","V5":"La descente","V6":"La cabine du propriétaire"}}}'::jsonb, '{"en":{"Composite":"Composite","Francesco Paszkowski":"Francesco Paszkowski","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 cabins: owner''s suite, 1 VIP, 2 doubles, 1 twin","2 × MTU 12V 2000 M96L":"2 × MTU 12V 2000 M96L","Gyroscopiques":"Gyroscopic","Vingt-huit nœuds, et l''Estérel pour horizon.":"Twenty‑eight knots, with the Estérel on the horizon.","Tramontane est le plus vif de la flotte : il relie Saint-Tropez à Cannes en une heure, et laisse le temps de déjeuner aux îles de Lérins avant de rentrer. Sa coque grise et ses vitrages teintés lui donnent une allure de sport.":"Tramontane is the liveliest of the fleet: she runs from Saint‑Tropez to Cannes in an hour, leaving time for lunch at the Lérins islands before heading home. Her grey hull and tinted glazing give her a sporting look.","À bord, l''eucalyptus gris, le cuir noir et l''acier brossé composent un intérieur tenu, presque architectural. Le fly, abrité par un hard-top, devient le salon principal dès que le soleil est haut.":"On board, grey eucalyptus, black leather and brushed steel make for a disciplined, almost architectural interior. The flybridge, sheltered by a hardtop, becomes the main lounge as soon as the sun is high.","28 nœuds":"28 knots","Saint-Tropez à Cannes en une heure":"Saint‑Tropez to Cannes in one hour","Fly":"Flybridge","Salon, bar et bains de soleil à l''ombre d''un hard-top":"Lounge, bar and sunpads in the shade of a hardtop","Tirant d''eau réduit":"Shallow draught","Mouillages au plus près des calanques de l''Estérel":"Anchoring close in to the Estérel''s coves","Poste de pilotage, bar, salon d''extérieur, bains de soleil":"Helm station, bar, outdoor lounge, sunpads","Pont principal":"Main deck","Cockpit, salon, salle à manger, suite du propriétaire":"Cockpit, saloon, dining room, owner''s suite","Pont inférieur":"Lower deck","1 VIP, 2 doubles, 1 twin":"1 VIP, 2 doubles, 1 twin","Le yacht Tramontane lancé à pleine vitesse le long des roches rouges de l''Estérel":"The yacht Tramontane at full speed along the red rocks of the Estérel","Extérieur":"Exterior","Tramontane lancé à pleine vitesse le long de l''Estérel":"Tramontane at full speed along the Estérel","La plage arrière au ras de l''eau, au mouillage dans une calanque de l''Estérel":"The swim platform at water level, at anchor in a cove of the Estérel","Le salon de Tramontane : eucalyptus gris, cuir noir et pierre claire, face aux roches rouges":"Tramontane''s saloon: grey eucalyptus, black leather and pale stone, facing the red rocks","La cabine du propriétaire, tête de lit en cuir noir et baie ouverte sur l''Estérel":"The owner''s cabin, with a black leather headboard and a window open onto the Estérel","Le fly de Tramontane, abrité par son hard-top : bar, poste de pilotage et bains de soleil":"Tramontane''s flybridge under its hardtop: bar, helm station and sunpads","Au mouillage, Estérel":"At anchor, Estérel","La plage arrière":"The swim platform","Le cockpit":"The cockpit","Le salon":"The saloon","La descente":"The companionway","La cabine du propriétaire":"The owner''s cabin"},"de":{"Composite":"Verbundwerkstoff","Francesco Paszkowski":"Francesco Paszkowski","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 Kabinen: Eignersuite, 1 VIP, 2 Doppel, 1 Twin","2 × MTU 12V 2000 M96L":"2 × MTU 12V 2000 M96L","Gyroscopiques":"Gyroskopisch","Vingt-huit nœuds, et l''Estérel pour horizon.":"Achtundzwanzig Knoten, und das Esterel am Horizont.","Tramontane est le plus vif de la flotte : il relie Saint-Tropez à Cannes en une heure, et laisse le temps de déjeuner aux îles de Lérins avant de rentrer. Sa coque grise et ses vitrages teintés lui donnent une allure de sport.":"Tramontane ist die lebhafteste der Flotte: Sie fährt in einer Stunde von Saint‑Tropez nach Cannes und lässt Zeit für ein Mittagessen auf den Lérins-Inseln vor der Rückfahrt. Grauer Rumpf und getönte Scheiben geben ihr eine sportliche Linie.","À bord, l''eucalyptus gris, le cuir noir et l''acier brossé composent un intérieur tenu, presque architectural. Le fly, abrité par un hard-top, devient le salon principal dès que le soleil est haut.":"An Bord ergeben graues Eukalyptusholz, schwarzes Leder und gebürsteter Stahl ein strenges, fast architektonisches Interieur. Die Flybridge unter ihrem Hardtop wird zum Hauptsalon, sobald die Sonne hoch steht.","28 nœuds":"28 Knoten","Saint-Tropez à Cannes en une heure":"Von Saint‑Tropez nach Cannes in einer Stunde","Fly":"Flybridge","Salon, bar et bains de soleil à l''ombre d''un hard-top":"Lounge, Bar und Sonnenliegen im Schatten eines Hardtops","Tirant d''eau réduit":"Geringer Tiefgang","Mouillages au plus près des calanques de l''Estérel":"Ankerplätze ganz nah an den Buchten des Esterel","Poste de pilotage, bar, salon d''extérieur, bains de soleil":"Steuerstand, Bar, Außenlounge, Sonnenliegen","Pont principal":"Hauptdeck","Cockpit, salon, salle à manger, suite du propriétaire":"Cockpit, Salon, Esszimmer, Eignersuite","Pont inférieur":"Unterdeck","1 VIP, 2 doubles, 1 twin":"1 VIP, 2 Doppel, 1 Twin","Le yacht Tramontane lancé à pleine vitesse le long des roches rouges de l''Estérel":"Die Yacht Tramontane in voller Fahrt entlang der roten Felsen des Esterel","Extérieur":"Außen","Tramontane lancé à pleine vitesse le long de l''Estérel":"Tramontane in voller Fahrt entlang des Esterel","La plage arrière au ras de l''eau, au mouillage dans une calanque de l''Estérel":"Die Badeplattform direkt über dem Wasser, vor Anker in einer Bucht des Esterel","Le salon de Tramontane : eucalyptus gris, cuir noir et pierre claire, face aux roches rouges":"Der Salon der Tramontane: graues Eukalyptusholz, schwarzes Leder und heller Stein, mit Blick auf die roten Felsen","La cabine du propriétaire, tête de lit en cuir noir et baie ouverte sur l''Estérel":"Die Eignerkabine mit Kopfteil aus schwarzem Leder und Fensterfront zum Esterel","Le fly de Tramontane, abrité par son hard-top : bar, poste de pilotage et bains de soleil":"Die Flybridge der Tramontane unter ihrem Hardtop: Bar, Steuerstand und Sonnenliegen","Au mouillage, Estérel":"Vor Anker, Esterel","La plage arrière":"Die Badeplattform","Le cockpit":"Das Cockpit","Le salon":"Der Salon","La descente":"Der Niedergang","La cabine du propriétaire":"Die Eignerkabine"},"it":{"Composite":"Composito","Francesco Paszkowski":"Francesco Paszkowski","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 cabine: suite armatoriale, 1 VIP, 2 doppie, 1 twin","2 × MTU 12V 2000 M96L":"2 × MTU 12V 2000 M96L","Gyroscopiques":"Giroscopica","Vingt-huit nœuds, et l''Estérel pour horizon.":"Ventotto nodi, e l''Esterel all''orizzonte.","Tramontane est le plus vif de la flotte : il relie Saint-Tropez à Cannes en une heure, et laisse le temps de déjeuner aux îles de Lérins avant de rentrer. Sa coque grise et ses vitrages teintés lui donnent une allure de sport.":"Tramontane è il più vivace della flotta: collega Saint‑Tropez a Cannes in un''ora e lascia il tempo di pranzare alle isole di Lérins prima di rientrare. Lo scafo grigio e le vetrate oscurate gli danno un''aria sportiva.","À bord, l''eucalyptus gris, le cuir noir et l''acier brossé composent un intérieur tenu, presque architectural. Le fly, abrité par un hard-top, devient le salon principal dès que le soleil est haut.":"A bordo, l''eucalipto grigio, la pelle nera e l''acciaio spazzolato compongono interni rigorosi, quasi architettonici. Il fly, riparato da un hard top, diventa il salone principale non appena il sole è alto.","28 nœuds":"28 nodi","Saint-Tropez à Cannes en une heure":"Da Saint‑Tropez a Cannes in un''ora","Fly":"Flybridge","Salon, bar et bains de soleil à l''ombre d''un hard-top":"Salotto, bar e prendisole all''ombra di un hard top","Tirant d''eau réduit":"Pescaggio ridotto","Mouillages au plus près des calanques de l''Estérel":"Ancoraggi vicinissimi alle calette dell''Esterel","Poste de pilotage, bar, salon d''extérieur, bains de soleil":"Postazione di comando, bar, salotto esterno, prendisole","Pont principal":"Ponte principale","Cockpit, salon, salle à manger, suite du propriétaire":"Pozzetto, salone, sala da pranzo, suite armatoriale","Pont inférieur":"Ponte inferiore","1 VIP, 2 doubles, 1 twin":"1 VIP, 2 doppie, 1 twin","Le yacht Tramontane lancé à pleine vitesse le long des roches rouges de l''Estérel":"Lo yacht Tramontane lanciato a tutta velocità lungo le rocce rosse dell''Esterel","Extérieur":"Esterni","Tramontane lancé à pleine vitesse le long de l''Estérel":"Tramontane lanciato a tutta velocità lungo l''Esterel","La plage arrière au ras de l''eau, au mouillage dans une calanque de l''Estérel":"La piattaforma di poppa a pelo d''acqua, all''ancora in una caletta dell''Esterel","Le salon de Tramontane : eucalyptus gris, cuir noir et pierre claire, face aux roches rouges":"Il salone di Tramontane: eucalipto grigio, pelle nera e pietra chiara, di fronte alle rocce rosse","La cabine du propriétaire, tête de lit en cuir noir et baie ouverte sur l''Estérel":"La cabina armatoriale, testiera in pelle nera e vetrata aperta sull''Esterel","Le fly de Tramontane, abrité par son hard-top : bar, poste de pilotage et bains de soleil":"Il fly di Tramontane, riparato dal suo hard top: bar, postazione di comando e prendisole","Au mouillage, Estérel":"All''ancora, Esterel","La plage arrière":"La piattaforma di poppa","Le cockpit":"Il pozzetto","Le salon":"Il salone","La descente":"La discesa","La cabine du propriétaire":"La cabina armatoriale"}}'::jsonb)
