insert into public.yachts (slug, ordre, nom, invites, port, vente, location_basse, location_haute, fiche, traductions) values ('alize', 6, 'Alizé', 10, 'Saint-Tropez', 7900000, null, null, '{"selection":true,"exclusivite":false,"type":"moteur","chantier":"Sanlorenzo","chantierCourt":"Sanlorenzo","annee":2021,"refit":null,"longueur":29.2,"largeur":6.8,"tirant":1.9,"coque":"Composite","architecte":"Bernardo Zuccon","cabines":"5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin","equipage":5,"vitesse":{"croisiere":24,"max":28},"autonomie":300,"moteurs":"2 × MAN V12 1800","stabilisateurs":"Gyroscopiques","pavillon":"France","accroche":"Le premier yacht idéal : vif, lumineux, facile à vivre.","description":["Alizé a été pensé pour une famille qui navigue beaucoup : des volumes clairs, une grande terrasse avant, et une coque qui file à vingt-quatre nœuds sans bruit. Il se mène avec cinq membres d''équipage, ce qui garde ses frais d''exploitation raisonnables.","Le chêne blanchi, le travertin, le rotin et les tissus olive et terre cuite lui donnent un air de maison de vacances. Il est amarré au vieux port de Saint-Tropez, visible sur rendez-vous."],"points":[["Terrasse avant","Salon et bains de soleil sur la proue, à l''abri des regards"],["Frais maîtrisés","5 membres d''équipage, consommation contenue en croisière"],["Visible à Saint-Tropez","Amarré au vieux port, visite sur rendez-vous"]],"ponts":[["Fly","Poste de pilotage, bar, salon d''extérieur"],["Pont principal","Cockpit, salon, salle à manger, terrasse avant"],["Pont inférieur","Suite du propriétaire, 1 VIP, 2 doubles, 1 twin"]],"image":{"src":"flotte/alize","w":1536,"h":1024,"alt":"Le yacht Alizé au mouillage devant Saint-Tropez, au lever du soleil"},"galerie":[{"src":"flotte/alize","w":1536,"h":1024,"pont":"Extérieur","alt":"Alizé au mouillage dans le golfe de Saint-Tropez, au lever du soleil"},{"src":"galerie/alize-cockpit","w":1536,"h":1024,"pont":"Pont principal","alt":"La table du cockpit dressée pour six, face au vieux port de Saint-Tropez au couchant"},{"src":"galerie/alize-salon","w":1536,"h":1024,"pont":"Pont principal","alt":"Le salon d''Alizé : chêne blanchi, travertin, rotin et coussins olive et terre cuite"},{"src":"galerie/alize-terrasse","w":1536,"h":1024,"pont":"Pont principal","alt":"La terrasse avant d''Alizé au coucher du soleil, face à Saint-Tropez"},{"src":"galerie/alize-cabine","w":1536,"h":1024,"pont":"Pont inférieur","alt":"La cabine du propriétaire, tête de lit en rotin et plaid terre cuite, ouverte sur la mer"}],"visite":{"dir":"visites/alize","affiche":"visites/alize/affiche","duree":"Cinq étapes, du quai du vieux port à la terrasse avant, au coucher du soleil.","pieces":{"V1":"À quai, Saint-Tropez","V2":"Le cockpit","V3":"Le salon","V4":"Le passavant","V5":"La terrasse avant"}}}'::jsonb, '{"en":{"Composite":"Composite","Bernardo Zuccon":"Bernardo Zuccon","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 cabins: owner''s suite, 1 VIP, 2 doubles, 1 twin","2 × MAN V12 1800":"2 × MAN V12 1800","Gyroscopiques":"Gyroscopic","Le premier yacht idéal : vif, lumineux, facile à vivre.":"The ideal first yacht: lively, light‑filled, easy to live aboard.","Alizé a été pensé pour une famille qui navigue beaucoup : des volumes clairs, une grande terrasse avant, et une coque qui file à vingt-quatre nœuds sans bruit. Il se mène avec cinq membres d''équipage, ce qui garde ses frais d''exploitation raisonnables.":"Alizé was designed for a family that spends a lot of time at sea: bright volumes, a large foredeck terrace, and a hull that glides along at twenty‑four knots in near silence. She runs with a crew of five, which keeps her operating costs reasonable.","Le chêne blanchi, le travertin, le rotin et les tissus olive et terre cuite lui donnent un air de maison de vacances. Il est amarré au vieux port de Saint-Tropez, visible sur rendez-vous.":"Bleached oak, travertine, rattan and olive and terracotta fabrics give her the feel of a holiday home. She is moored in the old port of Saint‑Tropez and can be viewed by appointment.","Terrasse avant":"Foredeck terrace","Salon et bains de soleil sur la proue, à l''abri des regards":"Lounge and sunpads on the bow, away from prying eyes","Frais maîtrisés":"Controlled costs","5 membres d''équipage, consommation contenue en croisière":"A crew of 5, modest consumption at cruising speed","Visible à Saint-Tropez":"Viewing in Saint‑Tropez","Amarré au vieux port, visite sur rendez-vous":"Moored in the old port, viewing by appointment","Fly":"Flybridge","Poste de pilotage, bar, salon d''extérieur":"Helm station, bar, outdoor lounge","Pont principal":"Main deck","Cockpit, salon, salle à manger, terrasse avant":"Cockpit, saloon, dining room, foredeck terrace","Pont inférieur":"Lower deck","Suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"Owner''s suite, 1 VIP, 2 doubles, 1 twin","Le yacht Alizé au mouillage devant Saint-Tropez, au lever du soleil":"The yacht Alizé at anchor off Saint-Tropez at sunrise","Extérieur":"Exterior","Alizé au mouillage dans le golfe de Saint-Tropez, au lever du soleil":"Alizé at anchor in the Gulf of Saint‑Tropez at sunrise","La table du cockpit dressée pour six, face au vieux port de Saint-Tropez au couchant":"The cockpit table laid for six, facing the old port of Saint‑Tropez at sunset","Le salon d''Alizé : chêne blanchi, travertin, rotin et coussins olive et terre cuite":"Alizé''s saloon: bleached oak, travertine, rattan and olive and terracotta cushions","La terrasse avant d''Alizé au coucher du soleil, face à Saint-Tropez":"Alizé''s foredeck terrace at sunset, facing Saint‑Tropez","La cabine du propriétaire, tête de lit en rotin et plaid terre cuite, ouverte sur la mer":"The owner''s cabin, with a rattan headboard and terracotta throw, opening onto the sea","À quai, Saint-Tropez":"Moored, Saint‑Tropez","Le cockpit":"The cockpit","Le salon":"The saloon","Le passavant":"The side deck","La terrasse avant":"The foredeck terrace"},"de":{"Composite":"Verbundwerkstoff","Bernardo Zuccon":"Bernardo Zuccon","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 Kabinen: Eignersuite, 1 VIP, 2 Doppel, 1 Twin","2 × MAN V12 1800":"2 × MAN V12 1800","Gyroscopiques":"Gyroskopisch","Le premier yacht idéal : vif, lumineux, facile à vivre.":"Die ideale erste Yacht: lebendig, lichtdurchflutet, unkompliziert.","Alizé a été pensé pour une famille qui navigue beaucoup : des volumes clairs, une grande terrasse avant, et une coque qui file à vingt-quatre nœuds sans bruit. Il se mène avec cinq membres d''équipage, ce qui garde ses frais d''exploitation raisonnables.":"Alizé wurde für eine Familie entworfen, die viel auf dem Wasser ist: helle Räume, eine große Terrasse am Vorschiff und ein Rumpf, der lautlos mit vierundzwanzig Knoten gleitet. Sie wird mit fünf Crewmitgliedern gefahren, was die Betriebskosten im Rahmen hält.","Le chêne blanchi, le travertin, le rotin et les tissus olive et terre cuite lui donnent un air de maison de vacances. Il est amarré au vieux port de Saint-Tropez, visible sur rendez-vous.":"Gekalkte Eiche, Travertin, Rattan sowie oliv- und terrakottafarbene Stoffe verleihen ihr die Atmosphäre eines Ferienhauses. Sie liegt im alten Hafen von Saint‑Tropez und kann nach Vereinbarung besichtigt werden.","Terrasse avant":"Vorschiffsterrasse","Salon et bains de soleil sur la proue, à l''abri des regards":"Lounge und Sonnenliegen am Bug, vor Blicken geschützt","Frais maîtrisés":"Kontrollierte Kosten","5 membres d''équipage, consommation contenue en croisière":"5 Crewmitglieder, maßvoller Verbrauch bei Marschfahrt","Visible à Saint-Tropez":"Besichtigung in Saint‑Tropez","Amarré au vieux port, visite sur rendez-vous":"Im alten Hafen vertäut, Besichtigung nach Vereinbarung","Fly":"Flybridge","Poste de pilotage, bar, salon d''extérieur":"Steuerstand, Bar, Außenlounge","Pont principal":"Hauptdeck","Cockpit, salon, salle à manger, terrasse avant":"Cockpit, Salon, Esszimmer, Vorschiffsterrasse","Pont inférieur":"Unterdeck","Suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"Eignersuite, 1 VIP, 2 Doppel, 1 Twin","Le yacht Alizé au mouillage devant Saint-Tropez, au lever du soleil":"Die Yacht Alizé vor Anker vor Saint-Tropez bei Sonnenaufgang","Extérieur":"Außen","Alizé au mouillage dans le golfe de Saint-Tropez, au lever du soleil":"Alizé vor Anker im Golf von Saint-Tropez bei Sonnenaufgang","La table du cockpit dressée pour six, face au vieux port de Saint-Tropez au couchant":"Der Cockpittisch für sechs gedeckt, mit Blick auf den alten Hafen von Saint-Tropez bei Sonnenuntergang","Le salon d''Alizé : chêne blanchi, travertin, rotin et coussins olive et terre cuite":"Der Salon der Alizé: gekalkte Eiche, Travertin, Rattan und Kissen in Oliv und Terrakotta","La terrasse avant d''Alizé au coucher du soleil, face à Saint-Tropez":"Die Vorschiffsterrasse der Alizé bei Sonnenuntergang, mit Blick auf Saint-Tropez","La cabine du propriétaire, tête de lit en rotin et plaid terre cuite, ouverte sur la mer":"Die Eignerkabine mit Rattan-Kopfteil und terrakottafarbenem Plaid, zum Meer hin geöffnet","À quai, Saint-Tropez":"Am Kai, Saint‑Tropez","Le cockpit":"Das Cockpit","Le salon":"Der Salon","Le passavant":"Der Seitengang","La terrasse avant":"Die Vorschiffsterrasse"},"it":{"Composite":"Composito","Bernardo Zuccon":"Bernardo Zuccon","5 cabines : suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"5 cabine: suite armatoriale, 1 VIP, 2 doppie, 1 twin","2 × MAN V12 1800":"2 × MAN V12 1800","Gyroscopiques":"Giroscopica","Le premier yacht idéal : vif, lumineux, facile à vivre.":"Il primo yacht ideale: vivace, luminoso, facile da vivere.","Alizé a été pensé pour une famille qui navigue beaucoup : des volumes clairs, une grande terrasse avant, et une coque qui file à vingt-quatre nœuds sans bruit. Il se mène avec cinq membres d''équipage, ce qui garde ses frais d''exploitation raisonnables.":"Alizé è stato pensato per una famiglia che naviga molto: volumi luminosi, una grande terrazza di prua e uno scafo che fila a ventiquattro nodi in silenzio. Si conduce con cinque membri d''equipaggio, il che mantiene ragionevoli i costi di gestione.","Le chêne blanchi, le travertin, le rotin et les tissus olive et terre cuite lui donnent un air de maison de vacances. Il est amarré au vieux port de Saint-Tropez, visible sur rendez-vous.":"Il rovere sbiancato, il travertino, il rattan e i tessuti oliva e terracotta gli danno l''aria di una casa per le vacanze. È ormeggiato nel porto vecchio di Saint‑Tropez, visitabile su appuntamento.","Terrasse avant":"Terrazza di prua","Salon et bains de soleil sur la proue, à l''abri des regards":"Salotto e prendisole a prua, al riparo dagli sguardi","Frais maîtrisés":"Costi contenuti","5 membres d''équipage, consommation contenue en croisière":"5 membri d''equipaggio, consumi contenuti in crociera","Visible à Saint-Tropez":"Visitabile a Saint‑Tropez","Amarré au vieux port, visite sur rendez-vous":"Ormeggiato nel porto vecchio, visita su appuntamento","Fly":"Flybridge","Poste de pilotage, bar, salon d''extérieur":"Postazione di comando, bar, salotto esterno","Pont principal":"Ponte principale","Cockpit, salon, salle à manger, terrasse avant":"Pozzetto, salone, sala da pranzo, terrazza di prua","Pont inférieur":"Ponte inferiore","Suite du propriétaire, 1 VIP, 2 doubles, 1 twin":"Suite armatoriale, 1 VIP, 2 doppie, 1 twin","Le yacht Alizé au mouillage devant Saint-Tropez, au lever du soleil":"Lo yacht Alizé all''ancora davanti a Saint-Tropez, all''alba","Extérieur":"Esterni","Alizé au mouillage dans le golfe de Saint-Tropez, au lever du soleil":"Alizé all''ancora nel golfo di Saint-Tropez, all''alba","La table du cockpit dressée pour six, face au vieux port de Saint-Tropez au couchant":"La tavola del pozzetto apparecchiata per sei, di fronte al porto vecchio di Saint-Tropez al tramonto","Le salon d''Alizé : chêne blanchi, travertin, rotin et coussins olive et terre cuite":"Il salone di Alizé: rovere sbiancato, travertino, rattan e cuscini oliva e terracotta","La terrasse avant d''Alizé au coucher du soleil, face à Saint-Tropez":"La terrazza di prua di Alizé al tramonto, di fronte a Saint-Tropez","La cabine du propriétaire, tête de lit en rotin et plaid terre cuite, ouverte sur la mer":"La cabina armatoriale, testiera in rattan e plaid terracotta, aperta sul mare","À quai, Saint-Tropez":"In banchina, Saint‑Tropez","Le cockpit":"Il pozzetto","Le salon":"Il salone","Le passavant":"Il passavanti","La terrasse avant":"La terrazza di prua"}}'::jsonb)
